        def dfs(current):
            if current > limit:
                return
            if current > 0:
                lucky.append(current)
            dfs(current * 10 + 4)
            dfs(current * 10 + 7)
        dfs(0)
        return lucky

    lucky_numbers = generate_lucky(n)

