        memo = {}
        sizes_set = set(component_sizes)
        component_count = len(component_sizes)

        def solve(target):
            if target == 0:
                return 0
            if target in memo:
                return memo[target]

            for size in component_sizes:
                if size < target:
                    res = solve(target - size)
                    if res is not None:
                        memo[target] = res + 1
                        return memo[target]
            memo[target] = None
            return None

        for lucky in lucky_numbers:
            result = solve(lucky)
            if result is not None:
                return str(result - 1) + '\n'

        return '-1\n'

    memo = {}
    sizes_set = set(component_sizes)

    # Since the component count is up to 10^5, we need a more efficient approach
    # Use BFS to find minimum number of components for each lucky sum

    max_lucky = max(lucky_numbers) if lucky_numbers else 0
    if not lucky_numbers:
        return '-1\n'

    min_components = [float('inf')] * (max_lucky + 1)
    min_components[0] = 0

    queue = deque([0])

    while queue:
        current = queue.popleft()
        if current == max_lucky:
            break

        for size in component_sizes:
            if current + size <= max_lucky:
                comp_count = min_components[current]
                new_count = comp_count + 1 if comp_count > 0 else 1
                if new_count < min_components[current + size]:
                    min_components[current + size] = new_count
                    queue.append(current + size)

    for lucky in lucky_numbers:
        if min_components[lucky] < float('inf'):
            return str(min_components[lucky] - 1) + '\n'

