    if len(lines) < 2:
        return '0\n'

    n, k = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))
    pairs = []

    remaining_lines = lines[2:]
    for i in range(k):
        if 2 + i < len(lines):
            x, y = map(int, lines[2 + i].split())
            pairs.append((x, y))

    # Build the constraint graph
    # Adjacency list for topo sort
    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)

    # Add prerequisite edges
    valid_p = True
    for i in range(1, n + 1):
        parent = p[i - 1]
        if parent == 0:
            continue
        if parent < 1 or parent > n:
            return '0\n'
        adj[parent].append(i)
        in_degree[i] += 1

    # Add special pair edges
    for x, y in pairs:
        if x < 1 or x > n or y < 1 or y > n:
            return '0\n'
        adj[x].append(y)
        in_degree[y] += 1

    # Perform Kahn's algorithm for topological sort
    q = []
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            q.append(i)

    topo_order = []
    idx = 0
    while idx < len(q):
        node = q[idx]
        idx += 1
        topo_order.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                q.append(neighbor)

    if len(topo_order) != n:
        return '0\n'

    # Now check if special pairs appear consecutively
    topo_idx = {x: i for i, x in enumerate(topo_order)}
    valid = True
    for x, y in pairs:
        if abs(topo_idx[y] - topo_idx[x]) != 1:
            valid = False
            break

    if valid:
        return ' '.join(map(str, topo_order)) + '\n'
    else:
        return '0\n'
