def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    strings = lines[1:n+1]

    def get_sorted_form(s):
        return ''.join(sorted(s))

    def f(s_i, s_j):
        if s_i == s_j:
            return 0
        if ''.join(sorted(s_i)) == s_j:
            return 1
        if ''.join(sorted(s_j)) == s_i:
            return 1
        return 2

    # Group strings by their sorted character form
    from collections import defaultdict
    groups = defaultdict(list)

    for s in strings:
        key = get_sorted_form(s)
        groups[key].append(s)

    result = 0
    for group in groups.values():
        if len(group) > 1:
            for i in range(len(group)):
                for j in range(i + 1, len(group)):
                    result += f(group[i], group[j])

    # Format output as "\n{result}\n"
    return f"\n{result}\n"
```

