                xj = valid[j]

                # Calculate distance - should not go through blocked region
                # Try both paths and pick one that doesn't contain blocked trees
                dist1 = ci dest_dist(xi, xj)
                dist2 = dest_dist(xj, xi)

                # The valid distance is the one that doesn't pass through blocked
                # Simple check: if path is short, likely valid, otherwise blocked
                if dist1 <= dist2:
                    dist = dist1
                else:
                    dist = dist2

                energy = 2 * (h[xi - 1] + h[xj - 1]) + dist
                max_energy = max(max_energy, energy)

