def solution(s):
    lines = s.strip().split('\n')
    if not lines:
        return "-1 -1\n"

    try:
        n, m = map(int, lines[0].split())
    except:
        return "-1 -1\n"

    l = []
    r = []
    for i in range(n):
        try:
            parts = lines[1 + i].split()
            l.append(int(parts[0]))
            r.append(int(parts[1]))
        except:
            return "-1 -1\n"

    idx = 1 + n
    try:
        q = int(lines[idx])
    except:
        q = 0
    idx += 1

    known_scores = {}
    known_ranks = set()
    for i in range(q):
        if idx + i < len(lines):
            try:
                parts = lines[idx + i].split()
                p, sc = int(parts[0]), int(parts[1])
                known_scores[p] = sc
                known_ranks.add(p)
            except:
                idx += 1
        else:
            idx += 1

    try:
        t = int(lines[idx]) if idx < len(lines) else 0
    except:
        t = 0

    # Check basic sum constraints: total must be achievable
    sum_l = sum(l)
    sum_r = sum(r)

    if sum_l > t or sum_r < t:
        return "-1 -1\n"

    # Compute score bounds for each rank based on known scores
    # max_score[r] = max possible score for student at rank r
    # min_score[r] = min possible score for student at rank r

    max_score = [n] * (m + 2)
    min_score = [0] * (m + 2)

    # Initialize from known scores
    for p, sc in known_scores.items():
        max_score[p] = min(max_score[p], sc)
        min_score[p] = max(min_score[p], sc)

    # Merge overlapping constraints
    # For rank r: all known scores with ranks <= r have lower bound; known >= r have upper bound
    for r in range(1, m + 1):
        # Upper bound: min of all known scores at rank >= r
        ub = n
        for p, sc in known_scores.items():
            if p >= r:
                ub = min(ub, sc)
        max_score[r] = min(max_score[r], ub)

        # Lower bound: max of all known scores at rank <= r
        lb = 0
        for p, sc in known_scores.items():
            if p <= r:
                lb = max(lb, sc)
        min_score[r] = max(min_score[r], lb)

    # Find maximum k (students tied for first) and corresponding score
    best_k = 0
    best_s = 0
    possible = False

    # Try each possible score for rank 1
    for s in range(n + 1):
        # Check if this score is valid for rank 1
        if s < min_score[1] or s > max_score[1]:
            continue

        # Count how many consecutive students from rank 1 can have score s
        k = 0
        for r in range(1, m + 2):
            if r > 1 and s < min_score[r]:
                break
            if r - 1 <= m and s > max_score[r - 1]:
                break
            k += 1
        if k == 0:
            continue

        # Check if rank 1 has a known score - must match
        if 1 in known_scores and known_scores[1] != s:
            continue

        # Compute remaining total score needed
        remaining_total = t - k * s

        # Check if remaining students can achieve remaining_total
        # They need sum(min for their ranks) <= remaining_total <= sum(max for their ranks)
        if remaining_total < 0:
            continue

        rem_min_sum = 0
        rem_max_sum = 0
        for r in range(k + 1, m + 1):
            if min_score[r] > max_score[r] or min_score[r] < 0:
                continuous_valid = False
                break
            rem_min_sum += min_score[r]
            rem_max_sum += max_score[r]
            if rem_min_sum > remaining_total:
                continuous_valid = False
                break
            if rem_max_sum < remaining_total:
                continuous_valid = False
                break
        else:
            continuous_valid = True

        # Verify continuous score range (min to max scores form valid progression)
        valid_progression = True
        for r in range(1, k + 1):
            if min_score[r] > s or max_score[r] < s:
                valid_progression = False
                break

        if valid_progression and continuous_valid:
            if k > best_k or (k == best_k and s > best_s):
                best_k = k
                best_s = s
                possible = True

    if not possible:
        return "-1 -1\n"

    return f"{best_k} {best_s}\n"
