        lx_x, rx_x = 0.0, float('inf')
    else:
        t_enter_x = (x1 - rx) / vx
        t_exit_x = (x2 - rx) / vx

        if t_enter_x < 0 or t_exit_x >= t_enter_x:
            return (float('-inf'), float('-inf'))

        lx_x = t_enter_x
        rx_x = t_exit_x

    # Calculate y-axis interval
    if vy == 0:
        if not (y1 < ry < y2):
            return (float('-inf'), float('-inf'))
        ly_y, ry_y = 0.0, float('inf')
    else:
        t_enter_y = (y1 - ry) / vy
        t_exit_y = (y2 - ry) / vy

        if t_enter_y < 0 or t_exit_y >= t_enter_y:
            return (float('-inf'), float('-inf'))

        ly_y = t_enter_y
        ry_y = t_exit_y

    # Intersect x and y intervals
    L_mouse = max(lx_x, ly_y)
    R_mouse = min(rx_x, ry_y)

    if R_mouse <= L_mouse:
        return (float('-inf'), float('-inf'))

    return (L_mouse, R_mouse)


def solution(input_str: str) -> str:
    """
    Find the earliest time when all mice are strictly inside the mousetrap.

    For each mouse calculates when it's inside the rectangle on both x and y axes,
    takes the intersection for each mouse, then finds the overall intersection
    across all mice.
    """
    input_lines = input_str.strip().split('\n')
    idx = 1

    n = int(input_lines[idx])
    idx += 1

    x1, y1, x2, y2 = map(int, input_lines[idx].split())
    idx += 1

    global_L = float('-inf')
    global_R = float('inf')

    # Process each mouse
    for _ in range(n):
        rx, ry, vx, vy = map(int, input_lines[idx].split())
        idx += 1

        mouse_interval = get_interval(rx, ry, vx, vy, x1, y1, x2, y2)
        lx, rx = mouse_interval

        if lx == float('-inf'):
            return "-1"

        global_L = max(global_L, lx)
        global_R = min(global_R, rx)

        if global_L >= global_R:
            return "-1"

    # The answer is the maximum entry time, but must be non-negative
    ans = global_L
    if ans < 0:
        ans = 0.0

    # Format with enough precision
    return f"{ans:.14f}"


