    import math
    lines = input_str.strip().split('\n')
    a, v = map(int, lines[0].split())
    l, d, w = map(int, lines[1].split())

    def time_to_cover(start_spd, max_spd, distance, accel):
        if max_spd <= 0:
            return float('inf') if distance > 0 else 0.0
        if max_spd <= start_spd:
            return distance / max_spd

        dist_to_acceleration = (max_spd**2 - start_spd**2) / (2 * accel)
        if dist_to_acceleration >= distance:
            end_spd = math.sqrt(start_spd**2 + 2 * accel * distance)
            return (end_spd - start_spd) / accel
        else:
            return (max_spd - start_spd) / accel + (distance - dist_to_acceleration) / max_spd

    # Section 1: from 0 to d, ending at speed <= w
    w_reach_dist = w * w / (2 * a)

    if w > v:
        # Constraint is non-binding
        if v**2 / (2*a) >= d:
            v_d = math.sqrt(2 * a * d)
        else:
            v_d = v
    else:
        # Constraint matters
        peak = math.sqrt(a * d + w * w / 2)
        peak = min(peak, v)

        if d >= w_reach_dist:
            # Can reach w
            dist_to_v = v**2 / (2*a)
            decel_dist = (v**2 - w**2) / (2*a)
            dist_needed = dist_to_v + decel_dist

            if d >= dist_needed:
                # Accelerate to v, maintain, decelerate to w
                dist_const = d - dist_to_v - decel_dist
                v_d = w
                t1 = v/a + dist_const/v + (v-w)/a
            elif d >= dist_to_v:
                # Reach v but can't decelerate to w
                dist_dec_actual = d - dist_to_v
                v_at_d = math.sqrt(v**2 - 2 * a * dist_dec_actual)
                v_d = min(v_at_d, w)
                t1 = v/a + (v_d - v)/a
            else:
                # Can't reach v
                v_peak = min(peak, v)
                t1 = v_peak / a
                v_d = v_peak
        else:
            # Can't reach w
            v_peak = min(math.sqrt(2 * a * d), v)
            v_d = v_peak
            t1 = v_peak / a

    # Section 2: from d to l
    if w > v and d < v**2/(2*a):
        v_start = math.sqrt(2 * a * (l - d))
        if v_start > v:
            v_start = v
        t2 = (v - v_start) / a + (l - d - (v**2 - v_start**2)/(2*a))/v if v_start < v else (l - d) / v_start
    elif w > v:
        t2 = time_to_cover(v_d, v, l - d, a)
    else:
        t2 = time_to_cover(v_d, v, l - d, a)

    return f"{t1 + t2:.12f}"
