MOD = 10**9 + 7

def solution(input_str):
    parts = input_str.strip().split()
    if not parts:
        return '0'
    n = int(parts[0])
    k = int(parts[1])

    if n == 1:
        return '0'

    if k == 1:
        ans = (n - 1) * (n - 1) % MOD
        return str(ans)

    MAX_VAL = n - 1
    phi = list(range(MAX_VAL + 1))
    for i in range(2, MAX_VAL + 1):
        if phi[i] == i:
            for j in range(i, MAX_VAL + 1, i):
                phi[j] -= phi[j] // i
    phi[1] = 1

    # Prefix sum: phi_prefix[i] = sum(phi[1] to phi[i])
    phi_prefix = [0] * (MAX_VAL + 1)
    phi_prefix[1] = phi[1]
    for i in range(2, MAX_VAL + 1):
        phi_prefix[i] = (phi_prefix[i-1] + phi[i]) % MOD

    k_inv = pow(k, MOD - 2, MOD)

    # term1 = sum_{i=1}^{n-1} k^{-i}
    if MAX_VAL == 0:
        term1 = 0
    elif k_inv == 1:
        term1 = MAX_VAL % MOD
    else:
        # Geometric series: k_inv * (1 - k_inv^(n-1)) / (1 - k_inv)
        term1 = k_inv * (1 - pow(k_inv, MAX_VAL, MOD)) % MOD
        term1 = term1 * pow((k_inv - 1 + MOD) % MOD, MOD - 2, MOD) % MOD

    # term2 = sum_{g=1}^{n-1} k^{-g} * sum_{b=2}^{(n-1)/g} phi(b)
    term2 = 0
    for g in range(1, n):
        limit = MAX_VAL // g
        if limit < 2:
            continue
        phi_sum = (phi_prefix[limit] - phi_prefix[1]) % MOD
        term2 = (term2 + phi_sum * pow(k_inv, g, MOD)) % MOD

    ans = (term1 + 2 * term2) % MOD
    return str(ans)
