def solution(input_str):
    lines = input_str.strip().split('\n')
    F, B, N = map(int, lines[0].split())
    petal_counts = list(map(int, lines[1].split()))
    chocolate_counts = list(map(int, lines[2].split()))

    MOD = 1000000007

    max_box_sum = B * max(chocolate_counts)
    max_s = min(max_box_sum, max_box_sum + 2500)

    # Box DP
    dp = [0] * (max_s + 1)
    dp[0] = 1
    for c in chocolate_counts:
        for s in range(max_s, c - 1, -1):
            dp[s] = (dp[s] + dp[s - c]) % MOD

    # Matrix exponentiation for flowers
    M_size = max_s + 1
    M = [[0] * M_size for _ in range(M_size)]
    for p in petal_counts:
        if p < M_size:
            M[p][0] = 1

    def mat_mul(A, B):
        C = [[0] * M_size for _ in range(M_size)]
        for i in range(M_size):
            for k in range(M_size):
                if A[i][k]:
                    for j in range(M_size):
                        C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(A, n):
        result = [[0] * M_size for _ in range(M_size)]
        for i in range(M_size):
            result[i][i] = 1
        base = [row[:] for row in A]
        while n:
