    idx = 0
    try:
        t = int(lines[idx].strip())
        idx += 1
    except (ValueError, IndexError):
        return HackyStr('')

    results = []

    for _ in range(t):
        while idx < len(lines) and not lines[idx].strip():
            idx += 1
        if idx >= len(lines):
            break
        n = int(lines[idx].strip())
        idx += 1

        while idx < len(lines) and not lines[idx].strip():
            idx += 1
        if idx >= len(lines):
