Looking at this problem, I need to implement a parser for the given grammar that handles:
1. Basic number concatenation
2. Ranges (l-r): concatenation of all integers from l to r
3. Repetition (n(expr)): repeat expression n times
4. Addition (expr+term): concatenate results

The key challenge is that the results can be very large numbers that we need to compute modulo 10^9 + 7.

```python
MOD = 10**9 + 7

def solution(s):
    s = s.strip()
    n = len(s)
    pos = 0

    def parse_number():
        nonlocal pos
        start = pos
        while pos < n and s[pos].isdigit():
            pos += 1
        if start == pos:
            raise ValueError("Expected number")
        return int(s[start:pos])

    def parse_range(l, r):
        """Concatenate numbers from l to r"""
        result = []
        for i in range(l, r + 1):
            result.append(str(i))
        return int("".join(result))

    def parse_term():
        nonlocal pos
        num1 = parse_number()

        if pos < n and s[pos] == '-':
            pos += 1
            num2 = parse_number()
            return parse_range(num1, num2)
        elif pos < n and s[pos] == '(':
            pos += 1  # consume '('
            expr_result = parse_expression()
            if pos < n and s[pos] == ')':
                pos += 1  # consume ')'
            # Repeat expr_result, num1 times
            expr_str = str(expr_result)
            result_str = []
            for _ in range(num1):
                result_str.append(expr_str)
            return int("".join(result_str)) % MOD
        else:
            return num1

    def parse_expression():
        nonlocal pos
        result = parse_term()

        while pos < n and s[pos] == '+':
            pos += 1  # consume '+'
            term_result = parse_term()
            result = concatenate(result, term_result)

        return result

    def concatenate(a, b):
        """Concatenate a and b: a * 10^len(b) + b"""
        b_str = str(b)
        b_len = len(b_str)
        return (a * pow(10, b_len, MOD) + b) % MOD

    result = parse_expression()
    return str(result)
