import sys
from collections import deque


def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or len(lines) < 2:
        return ''

    n = int(lines[0].strip())

    # Build adjacency list (vertices are 1-indexed)
    graph = [[] for _ in range(n + 1)]
    for i in range(1, len(lines)):
        if i >= n:
            break
        try:
            u, v = map(int, lines[i].split())
            graph[u].append(v)
            graph[v].append(u)
        except:
            break

    def bfs(start):
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = deque([start])
        furthest = start
        max_dist = 0

        while queue:
            u = queue.popleft()
            if dist[u] > max_dist:
                max_dist = dist[u]
                furthest = u
            for v in graph[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return furthest, max_dist

    # Find tree diameter (in terms of number of vertices in longest path = diameter_nodes)
    if n <= 1:
        diameter_nodes = n
    else:
        _, farthest_from_1 = bfs(1)
        diameter_edges, _ = bfs(farthest_from_1)
        diameter_nodes = diameter_edges + 1

    results = []
    for k in range(1, n + 1):
        if k > n or k > diameter_nodes:
            results.append(str(0))
        else:
            results.append(str(n // k))

    return '\n'.join(results)
