                        dp[key] = current_len
                        parent[key] = parent.get(next_key)

                # Skip s2[j]
                next_key = (i, j - 1, state)
                if next_key in dp:
                    if current_len > dp[next_key]:
                        dp[key] = current_len
                        parent[key] = parent.get(next_key)

                # Match s1[i-1] == s2[j-1]
