    best_key = None
    for state in range(v + 1):
        key = (n, m, state)
        if key in dp and dp[key] > best_len:
            best_len = dp[key]
            best_key = key

    if best_len == 0:
        return '0'

    # Reconstruct solution
    result = []
    i, j, state = n, m, best_key[2] if best_key else 0

    while i > 0 or j > 0:
