    # KMP prefix function for pattern `virus`
    pi = [0] * v
    k = 0
    for i in range(1, v):
        while k > 0 and virus[k] != virus[i]:
            k = pi[k-1]
        if virus[k] == virus[i]:
            k += 1
        pi[i] = k

    def kmp_transition(state, char):
        """Compute next KMP state after processing character `char` from `state`"""
        while state > 0 and virus[state] != char:
            state = pi[state - 1]
        if virus[state] == char:
            state += 1
        return state  # Can return up to v (which triggers rejection)

    @lru_cache(maxsize=None)
    def solve(i, j, state):
        """Returns (length, subsequence_str) for LCS of s1[:i], s2[:j] with virus state `state`"""
        if i == 0 or j == 0:
