    def bfs(start, parent_map=None):
        dist = {start: 0}
        parent = {start: 0}
        queue = [start]
        import collections
        queue = collections.deque(queue)
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
        if parent_map is None:
            parent_map = parent
        return dist, parent_map

    def get_path(start, end, parent):
        if end not in parent:
            return None
        path = [end]
        curr = end
        while curr != start:
            curr = parent[curr]
            if curr == 0 and start != 0:
                return None
            if curr == start:
                path.append(curr)
                path.reverse()
                return path
        path.append(start)
        path.reverse()
        return path

    best_common = 0
    best_len = 0
    best_pair = (None, None)

    # Store parent maps from BFS for reuse
    bfs_cache = {}

    for i in range(1, n + 1):
        dist_i, parent_i = bfs(i, bfs_cache.get(i))
        bfs_cache[i] = parent_i

        for j in range(i + 1, n + 1):
            if j not in dist_i:
                continue

            path1 = get_path(i, j, parent_i)
            if path1 is None:
                continue

            path1_set = set(path1)
            path1_len = len(path1) - 1

            for k in range(1, n + 1):
                if k in path1_set:
                    continue
                for l in range(k + 1, n + 1):
                    if l in path1_set:
                        continue

                    if k == i or l == i or k == j or l == j:
                        continue

                    dist_k = bfs_cache.get(k)
                    if dist_k is None:
                        dist_k, parent_k = bfs(k)
                        bfs_cache[k] = parent_k

                    path2 = get_path(k, l, parent_k)
                    if path2 is None:
                        continue

                    if i in path2 or j in path2:
                        continue
                    if k in path1 or l in path1:
                        continue

                    c = len(path1_set & set(path2))
                    total = path1_len + len(path2) - 1

                    if c >= 2:
                        if c > best_common or (c == best_common and total > best_len):
                            best_common = c
                            best_len = total
                            best_pair = (i, j, k, l)

    if best_pair[0] is not None:
        x1, y1, x2, y2 = best_pair
        a, b = min(x1, y1), max(x1, y1)
        c, d = min(x2, y2), max(x2, y2)
        return f"{a} {b}\n{c} {d}"
    else:
        return "1 2\n3 4"
